CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO authenticated; GRANT UPDATE(display_name) ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_own_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid());
CREATE POLICY profiles_own_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.roomly_profile_signup() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id, coalesce(NEW.raw_user_meta_data->>'display_name','')); RETURN NEW; END $$;
CREATE TRIGGER roomly_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.roomly_profile_signup();
CREATE TABLE public.organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(trim(name)) BETWEEN 2 AND 100), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.organizations TO authenticated; GRANT ALL ON public.organizations TO service_role;
ALTER TABLE public.organizations ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.memberships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id), user_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,user_id), UNIQUE(user_id));
GRANT SELECT ON public.memberships TO authenticated; GRANT ALL ON public.memberships TO service_role;
ALTER TABLE public.memberships ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('admin','employee')), UNIQUE(organization_id,user_id), FOREIGN KEY(organization_id,user_id) REFERENCES public.memberships(organization_id,user_id));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.roomly_member(org uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.memberships WHERE organization_id=org AND user_id=auth.uid()) $$;
CREATE FUNCTION public.roomly_admin(org uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE organization_id=org AND user_id=auth.uid() AND role='admin') $$;
CREATE POLICY organizations_member ON public.organizations FOR SELECT TO authenticated USING(public.roomly_member(id));
CREATE POLICY memberships_member ON public.memberships FOR SELECT TO authenticated USING(public.roomly_member(organization_id));
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.roomly_admin(organization_id));
CREATE TABLE public.rooms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id), name text NOT NULL CHECK(length(trim(name)) BETWEEN 2 AND 100), location text NOT NULL DEFAULT '', capacity integer NOT NULL CHECK(capacity>0), description text NOT NULL DEFAULT '', equipment text[] NOT NULL DEFAULT '{}', is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,organization_id));
GRANT SELECT ON public.rooms TO authenticated; GRANT ALL ON public.rooms TO service_role;
ALTER TABLE public.rooms ENABLE ROW LEVEL SECURITY;
CREATE POLICY rooms_member ON public.rooms FOR SELECT TO authenticated USING(public.roomly_member(organization_id));
CREATE TABLE public.reservations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id), room_id uuid NOT NULL, user_id uuid NOT NULL, title text NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 150), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'active' CHECK(status IN('active','cancelled')), created_at timestamptz NOT NULL DEFAULT now(), CHECK(ends_at>starts_at), FOREIGN KEY(room_id,organization_id) REFERENCES public.rooms(id,organization_id), EXCLUDE USING gist(room_id WITH =, tstzrange(starts_at,ends_at,'[)') WITH &&) WHERE(status='active'));
GRANT SELECT ON public.reservations TO authenticated; GRANT ALL ON public.reservations TO service_role;
ALTER TABLE public.reservations ENABLE ROW LEVEL SECURITY;
CREATE POLICY reservations_private ON public.reservations FOR SELECT TO authenticated USING(public.roomly_member(organization_id) AND(user_id=auth.uid() OR public.roomly_admin(organization_id)));
CREATE INDEX rooms_org_idx ON public.rooms(organization_id); CREATE INDEX reservations_org_time_idx ON public.reservations(organization_id,starts_at); CREATE INDEX reservations_user_idx ON public.reservations(user_id); CREATE INDEX roles_user_idx ON public.user_roles(user_id);
CREATE TABLE public.audit_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id), user_id uuid NOT NULL, action text NOT NULL, object_id uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.audit_events TO authenticated; GRANT ALL ON public.audit_events TO service_role;
ALTER TABLE public.audit_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_admin ON public.audit_events FOR SELECT TO authenticated USING(public.roomly_admin(organization_id));
CREATE INDEX audit_org_idx ON public.audit_events(organization_id);
CREATE FUNCTION public.roomly_create_organization(org_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE org uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Zaloguj się.'; END IF; IF EXISTS(SELECT 1 FROM public.memberships WHERE user_id=auth.uid()) THEN RAISE EXCEPTION 'Masz już organizację.'; END IF; INSERT INTO public.organizations(name) VALUES(trim(org_name)) RETURNING id INTO org; INSERT INTO public.memberships(organization_id,user_id) VALUES(org,auth.uid()); INSERT INTO public.user_roles(organization_id,user_id,role) VALUES(org,auth.uid(),'admin'); RETURN org; END $$;
CREATE FUNCTION public.roomly_book(org uuid, room uuid, meeting_title text, starts timestamptz, ends timestamptz) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE booking uuid; BEGIN IF NOT public.roomly_member(org) THEN RAISE EXCEPTION 'Brak dostępu do organizacji.'; END IF; IF starts<=now() THEN RAISE EXCEPTION 'Rezerwacja musi dotyczyć przyszłego terminu.'; END IF; PERFORM 1 FROM public.rooms WHERE id=room AND organization_id=org AND is_active FOR SHARE; IF NOT FOUND THEN RAISE EXCEPTION 'Sala jest nieaktywna lub niedostępna.'; END IF; INSERT INTO public.reservations(organization_id,room_id,user_id,title,starts_at,ends_at) VALUES(org,room,auth.uid(),trim(meeting_title),starts,ends) RETURNING id INTO booking; INSERT INTO public.audit_events(organization_id,user_id,action,object_id) VALUES(org,auth.uid(),'reservation_created',booking); RETURN booking; END $$;
CREATE FUNCTION public.roomly_cancel(booking uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.reservations; BEGIN SELECT * INTO r FROM public.reservations WHERE id=booking FOR UPDATE; IF r.id IS NULL OR NOT public.roomly_member(r.organization_id) OR NOT(public.roomly_admin(r.organization_id) OR (r.user_id=auth.uid() AND r.starts_at>now())) THEN RAISE EXCEPTION 'Nie możesz anulować tej rezerwacji.'; END IF; UPDATE public.reservations SET status='cancelled' WHERE id=booking; INSERT INTO public.audit_events(organization_id,user_id,action,object_id) VALUES(r.organization_id,auth.uid(),'reservation_cancelled',booking); END $$;
CREATE FUNCTION public.roomly_save_room(org uuid, room uuid, room_name text, room_location text, room_capacity integer, room_description text, room_equipment text[], active boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN IF NOT public.roomly_admin(org) THEN RAISE EXCEPTION 'Wymagane uprawnienia administratora.'; END IF; IF room IS NULL THEN INSERT INTO public.rooms(organization_id,name,location,capacity,description,equipment,is_active) VALUES(org,trim(room_name),room_location,room_capacity,room_description,room_equipment,active) RETURNING id INTO result; ELSE UPDATE public.rooms SET name=trim(room_name),location=room_location,capacity=room_capacity,description=room_description,equipment=room_equipment,is_active=active WHERE id=room AND organization_id=org RETURNING id INTO result; IF result IS NULL THEN RAISE EXCEPTION 'Sala nie należy do tej organizacji.'; END IF; END IF; INSERT INTO public.audit_events(organization_id,user_id,action,object_id) VALUES(org,auth.uid(),'room_saved',result); RETURN result; END $$;
CREATE FUNCTION public.roomly_set_role(org uuid, target uuid, new_role text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.roomly_admin(org) THEN RAISE EXCEPTION 'Wymagane uprawnienia administratora.'; END IF; PERFORM 1 FROM public.organizations WHERE id=org FOR UPDATE; IF new_role='employee' AND EXISTS(SELECT 1 FROM public.user_roles WHERE organization_id=org AND user_id=target AND role='admin') AND (SELECT count(*) FROM public.user_roles WHERE organization_id=org AND role='admin')<=1 THEN RAISE EXCEPTION 'Organizacja musi mieć administratora.'; END IF; UPDATE public.user_roles SET role=new_role WHERE organization_id=org AND user_id=target; IF NOT FOUND THEN RAISE EXCEPTION 'Użytkownik nie należy do organizacji.'; END IF; END $$;
CREATE FUNCTION public.roomly_workspace() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE org uuid; result jsonb; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Zaloguj się.'; END IF; SELECT organization_id INTO org FROM public.memberships WHERE user_id=auth.uid(); SELECT jsonb_build_object('organization',(SELECT jsonb_build_object('id',id,'name',name) FROM public.organizations WHERE id=org),'userId',auth.uid(),'displayName',coalesce((SELECT display_name FROM public.profiles WHERE id=auth.uid()),''),'role',coalesce((SELECT role FROM public.user_roles WHERE organization_id=org AND user_id=auth.uid()),'employee'),'rooms',coalesce((SELECT jsonb_agg(to_jsonb(r)) FROM public.rooms r WHERE organization_id=org),'[]'::jsonb),'reservations',coalesce((SELECT jsonb_agg(jsonb_build_object('id',CASE WHEN user_id=auth.uid() OR public.roomly_admin(org) THEN id::text ELSE 'busy-'||id::text END,'room_id',room_id,'user_id',CASE WHEN user_id=auth.uid() OR public.roomly_admin(org) THEN user_id::text ELSE '' END,'title',CASE WHEN user_id=auth.uid() OR public.roomly_admin(org) THEN title ELSE 'Zajęty termin' END,'starts_at',starts_at,'ends_at',ends_at,'status',status)) FROM public.reservations WHERE organization_id=org AND (starts_at>=now()-interval '90 days' AND starts_at<now()+interval '1 year')),'[]'::jsonb),'members',CASE WHEN public.roomly_admin(org) THEN coalesce((SELECT jsonb_agg(jsonb_build_object('user_id',m.user_id,'role',u.role,'display_name',coalesce(p.display_name,''))) FROM public.memberships m JOIN public.user_roles u ON u.organization_id=m.organization_id AND u.user_id=m.user_id LEFT JOIN public.profiles p ON p.id=m.user_id WHERE m.organization_id=org),'[]'::jsonb) ELSE '[]'::jsonb END) INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.roomly_member(uuid), public.roomly_admin(uuid), public.roomly_create_organization(text), public.roomly_book(uuid,uuid,text,timestamptz,timestamptz), public.roomly_cancel(uuid), public.roomly_save_room(uuid,uuid,text,text,integer,text,text[],boolean), public.roomly_set_role(uuid,uuid,text), public.roomly_workspace() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.roomly_member(uuid), public.roomly_admin(uuid), public.roomly_create_organization(text), public.roomly_book(uuid,uuid,text,timestamptz,timestamptz), public.roomly_cancel(uuid), public.roomly_save_room(uuid,uuid,text,text,integer,text,text[],boolean), public.roomly_set_role(uuid,uuid,text), public.roomly_workspace() TO authenticated, service_role;